import{_ as a,o as d,c as e,aO as r}from"./chunks/framework.BFrk9dwu.js";const p=JSON.parse('{"title":"基础介绍","description":"","frontmatter":{"date":"2026-11-27T11:05:31.000Z","title":"基础介绍","sidebarSort":1,"categories":["ai"],"permalink":"/pages/246502"},"headers":[],"relativePath":"ai/02.LangChain/index.md","filePath":"ai/02.LangChain/index.md","lastUpdated":1795773654000}'),n={name:"ai/02.LangChain/index.md"};function i(o,t,h,l,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="基础介绍" tabindex="-1">基础介绍 <a class="header-anchor" href="#基础介绍" aria-label="Permalink to &quot;基础介绍&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>LangChain 是一个<strong>把「模型调用」拆成可组合零件</strong>的编排框架。它本身不含智能，只负责把提示词、模型、工具、检索这些东西串成一条可维护的流水线。</p><p>一句话定位：<strong>当你的流程超过两步、需要分支和重试时，别再手写胶水代码。</strong></p><h2 id="有什么用" tabindex="-1">有什么用 <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用&quot;">​</a></h2><p>手写调用的代价在三个地方显形：换模型要改多处、加重试和日志要重新包一层、多步流程全挤在一个函数里没法测。</p><table tabindex="0"><thead><tr><th>不用框架</th><th>用了框架</th></tr></thead><tbody><tr><td>每家 SDK 的入参格式各写一遍</td><td>统一成 message 结构，换模型只改一行</td></tr><tr><td>重试、超时、日志手工拼</td><td>用 <code>Runnable</code> 串起来，<code>.with_retry()</code> 一行加</td></tr><tr><td>流程写死在函数里</td><td>每个环节独立可测、可替换</td></tr></tbody></table><p>但也要清楚：<strong>一句提示词就能解决的事，上框架是负担</strong>。它的价值随步骤数量增长。</p><h2 id="核心抽象" tabindex="-1">核心抽象 <a class="header-anchor" href="#核心抽象" aria-label="Permalink to &quot;核心抽象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>抽象</th><th>管什么</th></tr></thead><tbody><tr><td>ChatModel</td><td>一次模型调用，统一各家的消息格式</td></tr><tr><td>Message</td><td>system / human / ai / tool 四类角色，拼上下文</td></tr><tr><td>PromptTemplate</td><td>提示词模板，变量填充</td></tr><tr><td>OutputParser</td><td>把输出解析成 JSON 或结构化对象</td></tr><tr><td>Runnable</td><td>可组合单元，`</td></tr><tr><td>Tool / Function Calling</td><td>让模型决定调哪个外部函数</td></tr><tr><td>Retriever</td><td>检索接口，RAG 的入口</td></tr></tbody></table><h2 id="什么情况别用它" tabindex="-1">什么情况别用它 <a class="header-anchor" href="#什么情况别用它" aria-label="Permalink to &quot;什么情况别用它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>建议</th></tr></thead><tbody><tr><td>单轮问答、格式固定</td><td>直接调 SDK，少一层依赖</td></tr><tr><td>只做一个 RAG 检索</td><td>用向量库 SDK + 一次模型调用即可</td></tr><tr><td>需要复杂分支、循环、人工介入</td><td>上 LangGraph，普通 Chain 不够用</td></tr><tr><td>团队没人维护依赖树</td><td>版本锁死，或用更轻的封装</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>LangChain是智能体开发平台，包含一套各种帮助开发、测试、评估智能体的框架。核心包括：</p><ul><li>LangChain：用于快速构建智能体，可兼容任何模型提供商。</li><li>LangGraph：从底层一步步控制智能体的构建，包括记忆（Memory）、人机协同（HITL）等</li><li>Deep Agents：用于构建复杂的、处理多步骤的任务的智能体</li><li>LangSmith：用于测试、观察、评估、部署智能体</li></ul>',15)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
